# Private comparison of snapshots generated by the existing CIM serializer.
# Observed metadata excluded below is NOT configurable rule policy. All unknown
# properties remain in comparison. This is NOT an importer/restore authorization.
function Get-UfwSemanticRecord($Record){
 if($null -eq $Record -or $Record.rule.PSObject.Properties.Name -cnotcontains 'properties' -or $Record.associated_filters.PSObject.Properties.Name.Count -ne 7){throw 'ufw_unified_semantic_record_shape'}
 $ignored=@('PolicyStoreSource','PolicyStoreSourceType','PrimaryStatus','Status','EnforcementStatus')
 $props=[ordered]@{}
 foreach($p in @($Record.rule.properties.PSObject.Properties|Sort-Object Name -CaseSensitive)){
  if($p.Name -cnotin $ignored){$props[$p.Name]=$p.Value}
 }
 foreach($key in @('Name','Enabled','Action','Direction')){if(-not $props.Contains($key)){throw 'ufw_unified_semantic_required_property'}}
 $filters=[ordered]@{}
 foreach($kind in @('Address','Application','Interface','InterfaceType','Port','Security','Service')){
  if($Record.associated_filters.PSObject.Properties.Name -cnotcontains $kind){throw 'ufw_unified_semantic_filter_missing'}
  $filters[$kind]=$Record.associated_filters.$kind
 }
 return [pscustomobject]@{rule_class=$Record.rule.class;rule_namespace=$Record.rule.namespace;properties=[pscustomobject]$props;filters=[pscustomobject]$filters}
}
function Compare-UfwPrivateSnapshotPair($LocalRecord,$EffectiveRecord){
 # Both sides use captured type descriptors, not raw string coercion.
 $left=Get-UfwSemanticRecord $LocalRecord;$right=Get-UfwSemanticRecord $EffectiveRecord
 $l=ConvertTo-Json -InputObject $left -Depth 64 -Compress;$r=ConvertTo-Json -InputObject $right -Depth 64 -Compress
 return [pscustomobject]@{semantic_fields_match=($l -ceq $r);same_source_owner_verified=$false;fresh_native_policy_verified=$false;write_authority=$false;ready_for_apply=$false}
}
